        public func isEqual(to other: any ATProtocolValue) -> Bool {
            guard let other = other as? Self else { return false }
            if self.cid != other.cid {
                return false
            }
            if self.record != other.record {
                return false
            }
            return self.extraFields == other.extraFields
        }

        public static func == (lhs: Self, rhs: Self) -> Bool {
            return lhs.isEqual(to: rhs)
        }

        public func toCBORValue() throws -> Any {
            var map = OrderedCBORMap()
            let cidValue = try self.cid.toCBORValue()
            map = map.adding(key: "cid", value: cidValue)
            let recordValue = try self.record.toCBORValue()
            map = map.adding(key: "record", value: recordValue)
            return try ATProtocolValueContainer.addingExtraFields(extraFields, to: map)
        }

        private static let knownFieldKeys: Swift.Set<String> = ["$type", "cid", "record"]

        private enum CodingKeys: String, CodingKey {
            case cid
            case record
        }
    }

    public enum AudioCodec: String, Codable, ATProtocolCodable, ATProtocolValue, Sendable {
        case value_opus = "opus"

        public func isEqual(to other: any ATProtocolValue) -> Bool {
            guard let otherValue = other as? AudioCodec else { return false }
            return self == otherValue
        }

        public func toCBORValue() throws -> Any {
            return rawValue
        }
    }

    public enum VideoCodec: String, Codable, ATProtocolCodable, ATProtocolValue, Sendable {
        case value_h264 = "h264"

        public func isEqual(to other: any ATProtocolValue) -> Bool {
            guard let otherValue = other as? VideoCodec else { return false }
            return self == otherValue
        }

        public func toCBORValue() throws -> Any {
            return rawValue
        }
    }

}
